-- Stratagem Hero Expanded port, read-only live checks H0-H6 (build 26088801). Reads only, through Link's Link to
-- Memory (game, read, ptr, get, region, out, fmt; nothing here writes or calls a game function). Every pointer is
-- range-checked before it is followed. Generated by tools/make_probe.py (table bytes from the port's own
-- Mod.tables()). Run it on the ship (stratagem settings loaded), once with the option disabled and once enabled;
-- best also right after launch. See NOTES.md for what each line should show.
local G = assert(game, 'game.dll base')
local function ok(v) return v and v >= 0x10000 and v < 0x800000000000 end
local function P(a) if not ok(a) then return nil end local v = ptr(a) return ok(v) and v or nil end
local function U32(a) local s = ok(a) and read(a, 4) return s and get(s, 0, 'u32') or nil end
local function h(v) return v and fmt('0x%X', v) or 'nil' end
local function unhex(x) return (x:gsub('..', function(p) return string.char(tonumber(p, 16)) end)) end
local VANILLA_TIERS = unhex('')
local VANILLA_GROUPS = unhex('')
local EXPANDED_TIERS = unhex('')
local EXPANDED_GROUPS = unhex('')
local POOL = {104, 123, 14, 137, 57, 24, 99, 70, 44, 76, 118, 146, 59, 2, 31, 3, 51, 143, 18, 136, 68, 129, 39, 121, 86, 4, 139, 109, 128, 21, 64, 110, 60, 42, 77, 35, 117, 53, 103, 95, 33, 13, 58, 116, 144, 83, 134, 46, 84, 115, 63, 65, 153, 71, 151, 40, 16, 6, 102, 92, 25, 130, 133, 56, 78, 100, 113, 90, 124, 69, 8, 23, 55, 140, 120, 45, 54, 61, 22, 148, 9, 107, 108, 26, 138, 1, 52, 27, 10, 94, 91, 122, 142, 12, 47, 127, 34, 149, 43, 29, 11, 131, 19, 73, 5, 152, 119, 135}
local TIERS, GROUPS, SETTINGS, PROBE, TYPES = 0x24B5CC0, 0x24B5F70, 0x31870E0, 127, 154
out('SHE_LIVE game.dll', h(G))
do -- H0: the mod's own status table (same Lua state), when visible from here
  local okk, st = pcall(function() return rawget(_G, 'StratagemHeroExpanded') end)
  if okk and type(st) == 'table' then out('SHE_H0 version', st.version, 'status', st.status, 'applied', tostring(st.applied))
  else out('SHE_H0 status table not visible from this eval (read StratagemHeroExpanded.log)') end
end
do -- H1: game.dll .data section from the PE headers (the tables must lie inside it)
  local pe = U32(G + 0x3C)
  local hdr = pe and read(G + pe, 24)
  local n, opt = hdr and get(hdr, 6, 'u16') or 0, hdr and get(hdr, 20, 'u16') or 0
  for i = 0, n - 1 do
    local s = read(G + pe + 24 + opt + 40 * i, 40)
    local name = s:sub(1, 8):gsub('%z', '')
    if name == '.data' then
      local va, size = get(s, 12, 'u32'), get(s, 8, 'u32')
      out('SHE_H1 .data rva', h(va), 'size', h(size), 'tables inside', tostring(va <= TIERS and GROUPS + 640 <= va + size),
          '(want rva 0x24B5000, true)')
    end
  end
end
do -- H2: both arcade tables and the 76 bytes between them
  local all = read(G + TIERS, 612 + 76 + 640)
  if not all then out('SHE_H2 tables unreadable')
  else
    local tiers, gap, groups = all:sub(1, 612), all:sub(613, 688), all:sub(689)
    local state = (tiers == VANILLA_TIERS and groups == VANILLA_GROUPS) and 'vanilla'
        or (tiers == EXPANDED_TIERS and groups == EXPANDED_GROUPS) and 'expanded' or 'neither'
    out('SHE_H2 tiers vanilla', tostring(tiers == VANILLA_TIERS), 'expanded', tostring(tiers == EXPANDED_TIERS),
        '| groups vanilla', tostring(groups == VANILLA_GROUPS), 'expanded', tostring(groups == EXPANDED_GROUPS),
        '| state', state, '(vanilla without the option, expanded with it)')
    local g1 = {}
    for i = 0, 15 do local v = get(groups, 64 + 4 * i, 'u32') if v == 0 then break end g1[#g1 + 1] = v end
    out('SHE_H2 group 1', table.concat(g1, ','), '(vanilla 86,139,34,31,122,69; expanded starts 104,123,14,137)',
        'tier 0 banner', h(get(tiers, 0, 'u32')), '(0x4762C948)')
  end
end
do -- H3: the StratagemInfo table and every pool stratagem's settings, as Mod.check_pool reads them
  local probe = P(G + SETTINGS + 8 * PROBE)
  out('SHE_H3 settings table', h(G + SETTINGS), 'probe slot 127 (ReinforcementBeacon)', h(probe),
      'type', U32(probe), '(want 127)', '| slot 153', h(P(G + SETTINGS + 8 * 153)), '| slot 0', h(P(G + SETTINGS)))
  if probe then
    local bad, worst = 0, {}
    for _, k in ipairs(POOL) do
      local info = P(G + SETTINGS + 8 * k)
      local rec = info and read(info, 0xC0)
      local good = rec and get(rec, 0, 'u32') == k and get(rec, 0x48, 'u32') >= 1 and get(rec, 0x48, 'u32') <= 10
          and ok(get(rec, 0x40, 'u32') + get(rec, 0x44, 'u32') * 4294967296) and get(rec, 0xB8, 'u32') <= 4
      if not good then bad = bad + 1 if #worst < 8 then worst[#worst + 1] = k end end
    end
    out('SHE_H3 pool', #POOL, 'failing', bad, table.concat(worst, ','), '(want 108, 0)')
  end
end
do -- H4: the picker's code (read only; a page not yet resident reads as nil)
  local function hex(a, n) local okk, s = pcall(read, a, n) if not okk or not s then return 'nil' end
    return (s:gsub('.', function(c) return fmt('%02x', c:byte()) end)) end
  out('SHE_H4 picker +0x5A0F30', hex(G + 0x5A0F30, 16), '(want 48895c240848897c24108bc24d8bd84c)')
  out('SHE_H4 lea tiers +0x5A0F49', hex(G + 0x5A0F49, 7), '(want 488d05704df101)', 'lea groups +0x5A0FDB',
      hex(G + 0x5A0FDB, 7), '(want 488d058e4ff101)')
end
do -- H5: the region the mod's page check sees for both tables (the flagged MEM_MAPPED edit)
  for _, a in ipairs({TIERS, TIERS + 611, GROUPS, GROUPS + 639}) do
    local okk, r = pcall(region, G + a)
    if okk and type(r) == 'table' then
      out('SHE_H5 rva', h(a), fmt('state 0x%X type 0x%X protect 0x%X', r.state or -1, r.type or -1, r.protection or -1),
          'allocation base == game', tostring(r.allocation_base == nil and 'n/a' or r.allocation_base == G),
          '(want state 0x1000; type 0x40000 (MEM_MAPPED, as the edit expects) or 0x1000000; protect 0x8 before the '
          .. 'write, 0x8 or 0x4 after)')
    else out('SHE_H5 rva', h(a), 'region unavailable') end
  end
end
do -- H6: the old build's addresses (contrast: must not hold the tables)
  local old = read(G + 0x263CCC0, 612)
  out('SHE_H6 old tiers rva 0x263CCC0 holds vanilla tiers', tostring(old == VANILLA_TIERS), '(want false)')
end
return true
